void mainImage( out vec4 fragColor, in vec2 fragCoord)
{

    // spirograph parameters
    float freq_x = 150.;   // base frequency for x
    float freq_y = 100.;   // base frequency for y
    float ratio_x = .996;  // ratio between the two frequencies contributing to x
    float ratio_y = .998;   // ratio between the two frequencies contributing to y

    float brightness = 6400.;
    float persistanceTime = 1./20.;  // persistance of display in seconds
    const int numberOfSamples = 100;

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    vec2 coords = (fragCoord - iResolution.xy / 2.) / iResolution.y * 2.;

    float dist = distance(coords, vec2(0, 0));
    const int size = numberOfSamples;
    vec2 points[size];
    float dists[size];
    float spatialResponse[size];
    float temporalResponse[size];
    float sum = 0.;
    for(int i = 0; i < size; i++)
    {
        //points[i] = vec2(float(i - 5) / 10., float(i - 5) / 10.);

        float time = iTime + float(i) / float(size) * persistanceTime;

        // sample point on e-beam path
        //points[i] = vec2(0);
        //points[i] = vec2(cos(time * 800.), sin(250. * time)) / 1.3;  // sin cos
        points[i] = vec2(cos(freq_x * 2. * 3.1415 * time) + cos(ratio_x * freq_x * 2. * 3.1415 * time),
                         sin(freq_y * 2. * 3.1415 * time) + sin(ratio_y * freq_y * 2.  * 3.1415 * time)) / 2.; // spirograph
        //points[i] = vec2(mod(time * 60. * 100. * 2., 2.) - 1., mod(-time * 60. * 2., 2.) - 1.);  // raster scan

        //dists[i] = distance(coords, points[i]);  // distance from the test point (coords of pixel) to the sampled point


        if(i != 0)
        {
            vec2 lineVector = points[i] - points[i - 1];    // vector between two points on the line
            vec2 normalizedLineVector = normalize(lineVector);   // unit vector in direction of line
            vec2 linePoint = points[i];   // point on the line
            vec2 coordsToPoint = linePoint - coords;   // vector from test point (coords) to point on line
            float projectionLength = dot(normalizedLineVector, coordsToPoint);  // distance along line that test point is

            vec2 projectedToLine = normalizedLineVector * projectionLength;
            float lineDist = length(coordsToPoint - projectedToLine);
            //dists[i] = distance(coords, points[i]);
            //float nextDist;

            if(projectionLength < 0.)
            {
                dists[i] = distance(coords, points[i]);
                //dists[i] = 100000.;
            } else if(projectionLength > length(lineVector)) {
                dists[i] = distance(coords, points[i - 1]);
            } else {
                dists[i] = lineDist;
            }

            spatialResponse[i] = 0.;
            spatialResponse[i] += exp(-dists[i] * 180.) * brightness;    // main response exponential decay from beam spot
            spatialResponse[i] *= min(persistanceTime / float(size) / length(lineVector) * 100., 2.);  // brightness of a line based on it's dwell time
            spatialResponse[i] += min(1. / dists[i], 100.) * brightness / 3000.;   // out of focus bloom
            temporalResponse[i] = spatialResponse[i] * exp(-float(size - i - 1) / float(size) * 2.);
            //temporalResponse[i] = spatialResponse[i];
            sum += temporalResponse[i];
            //sum += 1. / lineDist;
        }

    }
    vec3 col = vec3(pow(sum / 1000., 0.75));
    //vec3 col = texture(iChannel0, coords).xyz * sum / 1000.;

    // Output to screen
    fragColor = vec4(col,1.0);
}
